+          </div>
+        </div>
+      </section>
+    `;
+
+    const Newsletter = () => `
+      <section class="newsletter" id="newsletter" aria-labelledby="newsletter-title">
+        <div class="newsletter-copy">
+          <p class="eyebrow">Northstar membership</p>
+          <h2 id="newsletter-title">Stay close to launches, offers, and new editorial drops.</h2>
+          <p>Join for early access, seasonal previews, and exclusive product notes delivered with restraint.</p>
