      --text: #f5f7fb;
      --muted: #a6b2c7;
      --line: #29405f;
      --brand: #8fd3ff;
      --brand-strong: #67bfff;
      --highlight: #ffd166;
      --success: #6ee7b7;
      --shadow: 0 22px 60px rgba(0, 0, 0, 0.38);
      --radius-xl: 28px;
      --radius-lg: 20px;
      --radius-md: 14px;
      --radius-sm: 10px;
      --page-width: 1200px;
    }

    * {
      box-sizing: border-box;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      margin: 0;
      min-width: 320px;
      font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top left, rgba(103, 191, 255, 0.14), transparent 28%),
        radial-gradient(circle at top right, rgba(255, 209, 102, 0.12), transparent 25%),
        linear-gradient(180deg, #07111f 0%, #091423 45%, #050b15 100%);
      line-height: 1.5;
    }

    a {
      color: inherit;
      text-decoration: none;
    }

    img {
      max-width: 100%;
      display: block;
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    button,
    input,
    select,
    textarea {
      font: inherit;
    }

    .skip-link {
      position: absolute;
      top: 1rem;
      left: 1rem;
      transform: translateY(-180%);
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: var(--text);
      color: #08101a;
      z-index: 1000;
      transition: transform 0.2s ease;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    .page-shell {
      width: min(calc(100% - 2rem), var(--page-width));
      margin: 0 auto;
    }

    .site-header {
      position: sticky;
      top: 0;
      z-index: 20;
      backdrop-filter: blur(18px);
      background: rgba(7, 17, 31, 0.8);
      border-bottom: 1px solid rgba(166, 178, 199, 0.12);
    }

    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding: 1rem 0;
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 0.85rem;
      font-weight: 700;
      letter-spacing: 0.02em;
    }

    .brand-mark {
      width: 2.5rem;
      height: 2.5rem;
      border-radius: 14px;
      background:
        linear-gradient(135deg, rgba(255, 209, 102, 0.95), rgba(103, 191, 255, 0.95));
      box-shadow: inset 0 1px 1px rgba(255, 255, 255, 0.3);
    }

    .site-nav ul,
    .utility-nav ul {
      display: flex;
      align-items: center;
      flex-wrap: wrap;
      gap: 0.75rem;
      padding: 0;
      margin: 0;
      list-style: none;
    }

    .site-nav a,
    .utility-nav a,
    .utility-nav button {
      color: var(--muted);
      border: 1px solid transparent;
      border-radius: 999px;
      padding: 0.55rem 0.9rem;
      background: transparent;
      cursor: pointer;
      transition: color 0.2s ease, border-color 0.2s ease, background 0.2s ease;
    }

    .site-nav a:hover,
    .site-nav a:focus-visible,
    .utility-nav a:hover,
    .utility-nav a:focus-visible,
    .utility-nav button:hover,
    .utility-nav button:focus-visible {
      color: var(--text);
      border-color: rgba(143, 211, 255, 0.35);
      background: rgba(143, 211, 255, 0.08);
    }

    .site-nav a:focus-visible,
    .utility-nav a:focus-visible,
    .utility-nav button:focus-visible,
    .cta-primary:focus-visible,
    .cta-secondary:focus-visible,
    .card-link:focus-visible,
    .newsletter-form button:focus-visible,
    .newsletter-form input:focus-visible {
      outline: 3px solid var(--highlight);
      outline-offset: 3px;
    }

    .header-actions {
      display: flex;
      align-items: center;
      gap: 1rem;
    }

    main {
      padding: 2rem 0 4rem;
    }

    .hero {
      display: grid;
      grid-template-columns: minmax(0, 1.2fr) minmax(280px, 0.8fr);
      gap: 1.5rem;
      align-items: stretch;
    }

    .hero-panel,
    .hero-aside,
    .section-surface,
    .newsletter {
      border: 1px solid rgba(166, 178, 199, 0.12);
      border-radius: var(--radius-xl);
      background: linear-gradient(180deg, rgba(19, 35, 58, 0.96), rgba(10, 20, 35, 0.98));
      box-shadow: var(--shadow);
    }

    .hero-panel {
      position: relative;
      overflow: hidden;
      padding: clamp(1.5rem, 3vw, 3rem);
      min-height: 520px;
      display: flex;
      flex-direction: column;
      justify-content: flex-end;
      gap: 1.25rem;
    }

    .hero-panel::before,
    .hero-panel::after {
      content: "";
      position: absolute;
      inset: auto;
      border-radius: 999px;
      pointer-events: none;
    }

    .hero-panel::before {
      width: 22rem;
      height: 22rem;
      top: -8rem;
      right: -8rem;
      background: radial-gradient(circle, rgba(103, 191, 255, 0.26), transparent 68%);
    }

    .hero-panel::after {
      width: 18rem;
      height: 18rem;
      bottom: -7rem;
      left: -5rem;
      background: radial-gradient(circle, rgba(255, 209, 102, 0.18), transparent 66%);
    }

    .eyebrow {
      display: inline-flex;
      width: fit-content;
      align-items: center;
      gap: 0.55rem;
      border-radius: 999px;
      padding: 0.45rem 0.8rem;
      background: rgba(143, 211, 255, 0.1);
      color: var(--brand);
      font-size: 0.9rem;
      font-weight: 600;
      letter-spacing: 0.02em;
    }

    .hero h1,
    .section-copy h2,
    .newsletter-copy h2 {
      margin: 0;
      line-height: 1.05;
      letter-spacing: -0.03em;
    }

    .hero h1 {
      max-width: 10ch;
      font-size: clamp(2.8rem, 7vw, 5.6rem);
    }

    .hero-copy {
      max-width: 40rem;
      font-size: 1.08rem;
      color: var(--muted);
    }

    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.85rem;
    }

    .cta-primary,
    .cta-secondary,
    .newsletter-form button {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-height: 3rem;
      padding: 0.85rem 1.2rem;
      border-radius: 999px;
      border: 1px solid transparent;
      font-weight: 700;
      cursor: pointer;
      transition: transform 0.2s ease, border-color 0.2s ease, background 0.2s ease;
    }

    .cta-primary,
    .newsletter-form button {
      background: linear-gradient(135deg, var(--brand), var(--brand-strong));
      color: #05111d;
    }

    .cta-secondary {
      border-color: rgba(166, 178, 199, 0.24);
      background: rgba(255, 255, 255, 0.03);
      color: var(--text);
    }

    .cta-primary:hover,
    .cta-secondary:hover,
    .newsletter-form button:hover {
      transform: translateY(-1px);
    }

    .hero-metrics {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 0.75rem;
      margin-top: 1rem;
    }

    .metric {
      padding: 1rem;
      border-radius: var(--radius-md);
      background: rgba(255, 255, 255, 0.04);
      border: 1px solid rgba(166, 178, 199, 0.12);
    }

    .metric strong {
      display: block;
      font-size: 1.25rem;
      margin-bottom: 0.3rem;
    }

    .metric span {
      color: var(--muted);
      font-size: 0.93rem;
    }

    .hero-aside {
      padding: 1.25rem;
      display: grid;
      gap: 1rem;
      align-content: start;
    }

    .aside-card {
      padding: 1.25rem;
      border-radius: var(--radius-lg);
      background: linear-gradient(180deg, rgba(255, 255, 255, 0.05), rgba(255, 255, 255, 0.02));
      border: 1px solid rgba(166, 178, 199, 0.12);
    }

    .aside-card h2,
    .aside-card h3,
    .product-card h3,
    .deal-card h3,
    .story-card h3 {
      margin-top: 0;
      margin-bottom: 0.5rem;
      font-size: 1.2rem;
    }

    .aside-card p,
    .deal-card p,
    .story-card p,
    .product-card p,
    .section-copy p,
    .newsletter-copy p {
      margin: 0;
      color: var(--muted);
    }

    .section-block {
      margin-top: 2rem;
      display: grid;
      gap: 1rem;
    }

    .section-surface,
    .newsletter {
      padding: clamp(1.25rem, 2vw, 2rem);
    }

    .section-heading {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 1rem;
      margin-bottom: 1.25rem;
    }

    .section-copy h2,
    .newsletter-copy h2 {
      font-size: clamp(1.8rem, 4vw, 2.6rem);
    }

    .section-link {
      color: var(--brand);
      font-weight: 600;
      white-space: nowrap;
    }

    .product-grid,
    .deal-grid,
    .story-grid {
      display: grid;
      gap: 1rem;
    }

    .product-grid {
      grid-template-columns: repeat(3, minmax(0, 1fr));
    }

    .deal-grid {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .story-grid {
      grid-template-columns: repeat(3, minmax(0, 1fr));
    }

    .product-card,
    .deal-card,
    .story-card {
      position: relative;
      min-width: 0;
      overflow: hidden;
      border-radius: var(--radius-lg);
      border: 1px solid rgba(166, 178, 199, 0.12);
      background: linear-gradient(180deg, rgba(255, 255, 255, 0.045), rgba(255, 255, 255, 0.015));
    }

    .card-visual {
      aspect-ratio: 4 / 3;
      border-bottom: 1px solid rgba(166, 178, 199, 0.12);
      background:
        radial-gradient(circle at top right, rgba(143, 211, 255, 0.35), transparent 35%),
        linear-gradient(135deg, rgba(26, 47, 79, 0.95), rgba(9, 20, 35, 1));
    }

    .card-content {
      padding: 1.15rem;
      display: grid;
      gap: 0.85rem;
    }

    .card-meta,
    .story-meta,
    .deal-meta {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      color: var(--muted);
      font-size: 0.92rem;
    }

    .price-line {
      display: flex;
      align-items: baseline;
      gap: 0.65rem;
      flex-wrap: wrap;
    }

    .price-current {
      font-size: 1.3rem;
      font-weight: 700;
    }

    .price-previous {
      color: var(--muted);
      text-decoration: line-through;
    }

    .pill {
      display: inline-flex;
      width: fit-content;
      padding: 0.35rem 0.6rem;
      border-radius: 999px;
      background: rgba(110, 231, 183, 0.12);
      color: var(--success);
      font-size: 0.82rem;
      font-weight: 700;
      letter-spacing: 0.02em;
    }

    .card-link {
      display: inline-flex;
      align-items: center;
      gap: 0.35rem;
      width: fit-content;
      color: var(--brand);
      font-weight: 600;
    }

    .deal-card {
      display: grid;
      grid-template-columns: minmax(160px, 0.85fr) minmax(0, 1.15fr);
    }

    .deal-card .card-visual {
      height: 100%;
      min-height: 240px;
      border-bottom: 0;
      border-right: 1px solid rgba(166, 178, 199, 0.12);
      background:
        radial-gradient(circle at top center, rgba(255, 209, 102, 0.32), transparent 35%),
        linear-gradient(180deg, rgba(31, 53, 84, 0.96), rgba(9, 18, 33, 1));
    }

    .story-card .card-visual {
      aspect-ratio: 16 / 10;
      background:
        linear-gradient(180deg, rgba(0, 0, 0, 0.05), rgba(0, 0, 0, 0.28)),
        radial-gradient(circle at bottom left, rgba(143, 211, 255, 0.22), transparent 28%),
        linear-gradient(135deg, rgba(26, 47, 79, 0.96), rgba(10, 18, 28, 1));
    }

    .newsletter {
      margin-top: 2rem;
      display: grid;
      grid-template-columns: minmax(0, 1fr) minmax(260px, 420px);
      gap: 1.5rem;
      align-items: center;
    }

    .newsletter-form {
      display: grid;
      gap: 0.75rem;
    }

    .newsletter-form label {
      display: grid;
      gap: 0.45rem;
      font-weight: 600;
    }

    .newsletter-form input {
      width: 100%;
      min-height: 3rem;
      padding: 0.85rem 1rem;
      border-radius: 999px;
      border: 1px solid rgba(166, 178, 199, 0.18);
      background: rgba(255, 255, 255, 0.03);
      color: var(--text);
    }

    .newsletter-note {
      margin-top: 0.75rem;
      font-size: 0.92rem;
      color: var(--muted);
    }

    .newsletter-status {
      min-height: 1.5rem;
      margin-top: 0.5rem;
      color: var(--success);
      font-size: 0.92rem;
      font-weight: 600;
    }

    .site-footer {
      padding: 1.5rem 0 2.5rem;
      color: var(--muted);
    }

    .footer-inner {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      flex-wrap: wrap;
      border-top: 1px solid rgba(166, 178, 199, 0.12);
      padding-top: 1.25rem;
    }

    @media (max-width: 980px) {
      .hero,
      .newsletter,
      .deal-card {
        grid-template-columns: 1fr;
      }

      .product-grid,
      .story-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      .deal-grid {
        grid-template-columns: 1fr;
      }

      .deal-card .card-visual {
        border-right: 0;
        border-bottom: 1px solid rgba(166, 178, 199, 0.12);
      }

      .site-nav {
        display: none;
      }
    }

    @media (max-width: 720px) {
      .page-shell {
        width: min(calc(100% - 1rem), var(--page-width));
      }

      .header-inner,
      .header-actions {
        flex-wrap: wrap;
      }

      .hero-panel {
        min-height: auto;
      }

      .hero h1 {
        max-width: 100%;
      }

      .hero-metrics,
      .product-grid,
      .story-grid {
        grid-template-columns: 1fr;
      }

      .section-heading {
        align-items: start;
        flex-direction: column;
      }
    }

    @media (forced-colors: active) {
      .hero-panel,
      .hero-aside,
      .section-surface,
      .newsletter,
      .product-card,
      .deal-card,
      .story-card,
      .aside-card,
      .metric {
        border-color: ButtonText;
      }

      .cta-primary,
      .cta-secondary,
      .newsletter-form button,
      .site-nav a,
      .utility-nav a,
      .utility-nav button,
      .newsletter-form input {
        forced-color-adjust: auto;
        border: 1px solid ButtonText;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <div id="app"></div>
  <script>
    const featuredProducts = [
      {
        category: "New Arrival",
        name: "Nocturne Wool Coat",
        description: "Tailored structure with a brushed finish for crisp city layers.",
        price: "$248",
        compareAt: "$320",
        badge: "Best seller"
      },
      {
        category: "Limited Run",
        name: "Signal Leather Weekender",
        description: "A clean-lined carryall built for overnight edits and weekday commutes.",
        price: "$196",
        compareAt: "$260",
        badge: "Low stock"
      },
      {
        category: "Staff Pick",
        name: "Studio Knit Set",
        description: "Soft merino essentials designed to mix elevated comfort with sharp texture.",
        price: "$142",
        compareAt: "$188",
        badge: "Online only"
      }
    ];

    const deals = [
      {
        title: "Weekend layering event",
        description: "Save on outerwear, knitwear, and accessories curated for transitional dressing.",
        details: "Up to 35% off",
        note: "Ends Sunday"
      },
      {
        title: "Home refresh bundle",
        description: "Bundle candles, throws, and table accents for a warm modern setup.",
        details: "Buy 2, get 1 free",
        note: "In-store and online"
      }
    ];

    const stories = [
      {
        category: "Editorial",
        title: "Three ways to style tonal layers after dark",
        description: "Explore soft contrast, premium texture, and the silhouettes defining the season.",
        meta: "5 minute read"
      },
      {
        category: "Journal",
        title: "Inside our buyers' edit for elevated essentials",
        description: "A closer look at the pieces balancing sharp tailoring with everyday ease.",
        meta: "Behind the collection"
      },
      {
        category: "Guide",
        title: "How to build a living room palette with depth",
        description: "Use low-light tones, brushed metals, and tactile accents to create a refined mood.",
        meta: "Design notes"
      }
    ];

    const metrics = [
      { value: "48 hr", label: "Fast dispatch on featured drops" },
      { value: "120+", label: "Curated products across fashion and home" },
      { value: "4.9/5", label: "Average rating from returning customers" }
    ];

    const Header = () => `
      <header class="site-header">
        <div class="page-shell header-inner">
          <a class="brand" href="#" aria-label="Northstar Atelier home">
            <span class="brand-mark" aria-hidden="true"></span>
            <span>Northstar Atelier</span>
          </a>
          <nav class="site-nav" aria-label="Primary">
            <ul>
              <li><a href="#featured-products">Featured</a></li>
              <li><a href="#deals">Deals</a></li>
              <li><a href="#editorial">Editorial</a></li>
              <li><a href="#newsletter">Membership</a></li>
            </ul>
          </nav>
          <div class="header-actions">
            <nav class="utility-nav" aria-label="Utilities">
              <ul>
                <li><a href="#newsletter">Sign in</a></li>
                <li><button type="button" aria-label="Open shopping bag">Bag (2)</button></li>
              </ul>
            </nav>
          </div>
        </div>
      </header>
    `;

    const HeroMetrics = () => `
      <div class="hero-metrics" aria-label="Store highlights">
        ${metrics.map((item) => `
          <div class="metric">
            <strong>${item.value}</strong>
            <span>${item.label}</span>
          </div>
        `).join("")}
      </div>
    `;

    const Hero = () => `
      <section class="hero" aria-labelledby="hero-heading">
        <div class="hero-panel">
          <span class="eyebrow">New season / dark essentials</span>
          <h1 id="hero-heading">Designed for modern retail moments.</h1>
          <p class="hero-copy">
            Discover premium wardrobe staples, considered home accents, and exclusive weekly edits
            selected to bring quiet luxury into everyday life.
          </p>
          <div class="hero-actions">
            <a class="cta-primary" href="#featured-products">Shop featured products</a>
            <a class="cta-secondary" href="#editorial">Read the journal</a>
          </div>
          ${HeroMetrics()}
        </div>
        <aside class="hero-aside" aria-label="Highlights">
          <section class="aside-card" aria-labelledby="curated-drop-title">
            <p class="eyebrow">Curated drop</p>
            <h2 id="curated-drop-title">After-hours tailoring with soft structure.</h2>
            <p>Clean coats, precise shirting, and understated accessories in tonal midnight finishes.</p>
          </section>
          <section class="aside-card" aria-labelledby="member-note-title">
            <p class="eyebrow">Member preview</p>
            <h2 id="member-note-title">Early access starts Thursday at 8 PM.</h2>
            <p>Subscribers unlock first access to capsule launches, brand stories, and styling notes.</p>
          </section>
        </aside>
      </section>
    `;

    const ProductCard = (product) => `
      <article class="product-card">
        <div class="card-visual" aria-hidden="true"></div>
        <div class="card-content">
          <div class="card-meta">
            <span>${product.category}</span>
            <span class="pill">${product.badge}</span>
          </div>
          <div>
            <h3>${product.name}</h3>
            <p>${product.description}</p>
          </div>
          <div class="price-line" aria-label="Price ${product.price}, previously ${product.compareAt}">
            <span class="price-current">${product.price}</span>
            <span class="price-previous">${product.compareAt}</span>
          </div>
          <a class="card-link" href="#newsletter" aria-label="Shop ${product.name}">Shop now</a>
        </div>
      </article>
    `;

    const FeaturedSection = () => `
      <section class="section-block" id="featured-products" aria-labelledby="featured-products-title">
        <div class="section-surface">
          <div class="section-heading">
            <div class="section-copy">
              <p class="eyebrow">Featured products</p>
              <h2 id="featured-products-title">The edit leading the season.</h2>
              <p>Signature pieces built to feel collectible, versatile, and immediately wearable.</p>
            </div>
            <a class="section-link" href="#newsletter">View member perks</a>
          </div>
          <div class="product-grid">
            ${featuredProducts.map(ProductCard).join("")}
          </div>
        </div>
      </section>
    `;

    const DealCard = (deal) => `
      <article class="deal-card">
        <div class="card-visual" aria-hidden="true"></div>
        <div class="card-content">
          <div class="deal-meta">
            <span class="eyebrow">Limited-time offer</span>
            <span>${deal.note}</span>
          </div>
          <div>
            <h3>${deal.title}</h3>
            <p>${deal.description}</p>
          </div>
          <div class="price-line">
            <span class="price-current">${deal.details}</span>
          </div>
          <a class="card-link" href="#newsletter" aria-label="Explore deal: ${deal.title}">Explore offer</a>
        </div>
      </article>
    `;

    const DealsSection = () => `
      <section class="section-block" id="deals" aria-labelledby="deals-title">
        <div class="section-surface">
          <div class="section-heading">
            <div class="section-copy">
              <p class="eyebrow">Deals</p>
              <h2 id="deals-title">Offers crafted to feel premium, not rushed.</h2>
              <p>Current savings across fashion and home, presented with clear value and a clean shopping path.</p>
            </div>
            <a class="section-link" href="#featured-products">Browse all featured lines</a>
          </div>
          <div class="deal-grid">
            ${deals.map(DealCard).join("")}
          </div>
        </div>
      </section>
    `;

    const StoryCard = (story) => `
      <article class="story-card">
        <div class="card-visual" aria-hidden="true"></div>
        <div class="card-content">
          <div class="story-meta">
            <span>${story.category}</span>
            <span>${story.meta}</span>
          </div>
          <div>
