      <section class="section-block" id="editorial" aria-labelledby="editorial-title">
        <div class="section-surface">
          <div class="section-heading">
            <div class="section-copy">
              <p class="eyebrow">Editorial content</p>
              <h2 id="editorial-title">Retail storytelling that supports discovery.</h2>
              <p>Give shoppers inspiration beyond the cart with styling advice, behind-the-scenes notes, and seasonal guides.</p>
            </div>
            <a class="section-link" href="#newsletter">Get weekly editorial drops</a>
          </div>
          <div class="story-grid">
            ${stories.map(StoryCard).join("")}
          </div>
        </div>
      </section>
    `;

    const Newsletter = () => `
      <section class="newsletter" id="newsletter" aria-labelledby="newsletter-title">
        <div class="newsletter-copy">
          <p class="eyebrow">Northstar membership</p>
          <h2 id="newsletter-title">Stay close to launches, offers, and new editorial drops.</h2>
          <p>Join for early access, seasonal previews, and exclusive product notes delivered with restraint.</p>
        </div>
        <div>
          <form class="newsletter-form" id="newsletter-form">
            <label for="email-address">
              <span>Email address</span>
              <input
                id="email-address"
                name="email"
                type="email"
                placeholder="name@example.com"
                autocomplete="email"
                required
                aria-describedby="newsletter-help newsletter-status"
              >
            </label>
            <button type="submit">Join now</button>
          </form>
          <p class="newsletter-note" id="newsletter-help">By joining, you agree to receive brand updates and curated editorial selections.</p>
          <p class="newsletter-status" id="newsletter-status" aria-live="polite"></p>
        </div>
      </section>
    `;

    const Footer = () => `
      <footer class="site-footer">
        <div class="page-shell footer-inner">
          <p>Northstar Atelier / refined goods for wardrobe and home</p>
          <p>Customer care, shipping, and store locations available upon request.</p>
        </div>
      </footer>
    `;

    const App = () => `
      ${Header()}
      <main id="main-content">
        <div class="page-shell">
          ${Hero()}
          ${FeaturedSection()}
          ${DealsSection()}
          ${EditorialSection()}
          ${Newsletter()}
        </div>
      </main>
      ${Footer()}
    `;

    document.getElementById("app").innerHTML = App();

    const newsletterForm = document.getElementById("newsletter-form");
    const newsletterStatus = document.getElementById("newsletter-status");

    newsletterForm.addEventListener("submit", (event) => {
      event.preventDefault();
      newsletterStatus.textContent = "Thanks for joining. Editorial updates and offer alerts are on the way.";
      newsletterForm.reset();
    });
  </script>
